--
-- WXYC prod-clone fixture for dev (`db-init` profile only).
--
-- Replaces the small artists/library/rotation/format/genre_artist_crossreference
-- seed from seed_db.sql with a `pg_dump --data-only --no-owner` snapshot of
-- those tables from the staging postgres (which itself clones prod).
--
-- Refresh recipe (~quarterly, when prod schema drift makes it worth):
--   1. `cd staging && docker compose up -d postgres` (port 5434)
--   2. `PGPASSWORD=postgres pg_dump -h localhost -p 5434 -U postgres -d wxyc_db \
--        --data-only --no-owner \
--        -t wxyc_schema.format \
--        -t wxyc_schema.artists \
--        -t wxyc_schema.genre_artist_crossreference \
--        -t wxyc_schema.library \
--        -t wxyc_schema.rotation \
--        > /tmp/dump.sql`
--   3. Strip pg_dump 18's `\restrict`/`\unrestrict` lines (psql < 18 doesn't
--      recognize them): `grep -v '^\\\(un\)\?restrict ' /tmp/dump.sql > dev_env/seed-clone.sql.body`
--   4. Replace the body of this file (everything after the leading TRUNCATE
--      block) with the dump body.
--
-- Mounted into the `db-init` container only (see docker-compose.yml). The
-- `ci-db-init` container does NOT mount this file, so CI integration tests
-- continue to run against the small seed_db.sql fixture and the fixed IDs
-- they depend on. See WXYC/Backend-Service#947.
--

BEGIN;

-- TRUNCATE the small fixture from seed_db.sql + every table that FKs into it.
-- RESTART IDENTITY resets sequences so the COPY blocks below land on the
-- prod-clone IDs (artists 1-24078, library 1-64193, etc.).
TRUNCATE
  wxyc_schema.flowsheet,
  wxyc_schema.bins,
  wxyc_schema.reviews,
  wxyc_schema.artist_library_crossreference,
  wxyc_schema.compilation_track_artist,
  wxyc_schema.library_identity,
  wxyc_schema.library_identity_source,
  wxyc_schema.artist_crossreference,
  wxyc_schema.genre_artist_crossreference,
  wxyc_schema.rotation,
  wxyc_schema.library,
  wxyc_schema.artists,
  wxyc_schema.format
RESTART IDENTITY CASCADE;

--
-- PostgreSQL database dump
--


-- Dumped from database version 17.9
-- Dumped by pg_dump version 18.4

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Data for Name: artists; Type: TABLE DATA; Schema: wxyc_schema; Owner: -
--



--
-- Data for Name: format; Type: TABLE DATA; Schema: wxyc_schema; Owner: -
--



--
-- Data for Name: genre_artist_crossreference; Type: TABLE DATA; Schema: wxyc_schema; Owner: -
--



--
-- Data for Name: library; Type: TABLE DATA; Schema: wxyc_schema; Owner: -
--



--
-- Data for Name: rotation; Type: TABLE DATA; Schema: wxyc_schema; Owner: -
--



--
-- Name: artists_id_seq; Type: SEQUENCE SET; Schema: wxyc_schema; Owner: -
--

SELECT pg_catalog.setval('wxyc_schema.artists_id_seq', 27050, true);


--
-- Name: format_id_seq; Type: SEQUENCE SET; Schema: wxyc_schema; Owner: -
--

SELECT pg_catalog.setval('wxyc_schema.format_id_seq', 6, true);


--
-- Name: library_id_seq; Type: SEQUENCE SET; Schema: wxyc_schema; Owner: -
--

SELECT pg_catalog.setval('wxyc_schema.library_id_seq', 70351, true);


--
-- Name: library_legacy_release_id_seq; Type: SEQUENCE SET; Schema: wxyc_schema; Owner: -
-- BS#1963: advance the Backend-mint sequence past the max legacy_release_id
-- loaded above (the 76 formerly-NULL rows now carry 1000000..1000075, mirroring
-- what the prod migration backfill produces) so the first dev catalog-add mint
-- cannot collide with a clone row under the unique library_legacy_release_id_idx.
--

SELECT pg_catalog.setval('wxyc_schema.library_legacy_release_id_seq', (SELECT GREATEST(MAX(legacy_release_id), 1000000) FROM wxyc_schema.library), true);


--
-- Name: rotation_id_seq; Type: SEQUENCE SET; Schema: wxyc_schema; Owner: -
--

SELECT pg_catalog.setval('wxyc_schema.rotation_id_seq', 21590, true);


--
-- PostgreSQL database dump complete
--


COMMIT;
